def short_to_long(odb: "GitCmdObjectDB", hexsha: str) -> Optional[bytes]:
    """:return: long hexadecimal sha1 from the given less-than-40 byte hexsha
        or None if no candidate could be found.
    :param hexsha: hexsha with less than 40 byte"""
    try:
        return bin_to_hex(odb.partial_to_complete_sha_hex(hexsha))
    except BadObject:
        return None


def name_to_object(
    repo: "Repo", name: str, return_ref: bool = False
) -> Union[SymbolicReference, "Commit", "TagObject", "Blob", "Tree"]:
    """
    :return: object specified by the given name, hexshas ( short and long )
        as well as references are supported
    :param return_ref: if name specifies a reference, we will return the reference
        instead of the object. Otherwise it will raise BadObject or BadName
    """
    hexsha: Union[None, str, bytes] = None

    if repo.re_hexsha_shortened.match(name):
        if len(name) != 40:
            hexsha = short_to_long(repo.odb, name)
        else:
            hexsha = name

    if hexsha is not None:
        if return_ref:
            return SymbolicReference(repo, name)
        else:
            return Object.new_from_sha(repo, hex_to_bin(hexsha))

    bases = ("", "refs/", "refs/tags/", "refs/heads/", "refs/remotes/", "refs/remotes//HEAD")
    for base in bases:
        try:
            hexsha = SymbolicReference.dereference_recursive(repo, base + name)
            if return_ref:
                return SymbolicReference(repo, base + name)
            break
        except ValueError:
            continue

    if return_ref:
        raise BadObject(f"Couldn't find reference named {name}")

    if hexsha is None:
        raise BadName(name)

    return Object.new_from_sha(repo, hex_to_bin(hexsha))


def deref_tag(tag: "Tag") -> "TagObject":
    """Recursively dereference a tag and return the resulting object"""
    while True:
        try:
            tag = tag.object
        except AttributeError:
            break
    return tag


