            end = rev.find("}", start)
            if end == -1:
                raise ValueError(f"Missing closing brace to define type in {rev}")
            output_type = rev[start + 1:end]
            start = end + 1

            if output_type == "commit":
                pass
            elif output_type == "tree":
                try:
                    obj = cast(Commit_ish, obj)
                    obj = to_commit(obj).tree
                except (AttributeError, ValueError):
                    pass
            elif output_type in ("", "blob"):
                obj = cast("TagObject", obj)
                if obj.type == "tag":
                    obj = deref_tag(obj)
            elif token == "@":
                revlog_index = None
                try:
                    revlog_index = -(int(output_type) + 1)
                except ValueError as e:
                    raise NotImplementedError("Support for additional @{...} modes not implemented") from e

                try:
                    entry = ref.log_entry(revlog_index)
                except IndexError as e:
                    raise IndexError(f"Invalid revlog index: {revlog_index}") from e

                obj = Object.new_from_sha(repo, hex_to_bin(entry.newhexsha))
                output_type = ""
            else:
                raise ValueError(f"Invalid output type: {output_type} (in {rev})")

            if output_type and obj and obj.type != output_type:
                raise ValueError(f"Could not accommodate requested object type {output_type}, got {obj.type}")
