        num = 0
        if token != ":":
            found_digit = False
            while start < len(rev) and rev[start] in digits:
                num = num * 10 + int(rev[start])
                start += 1
                found_digit = True

            if not found_digit:
                num = 1

        parsed_to = start

        try:
            obj = cast(Commit_ish, obj)
            if token == "~":
                obj = to_commit(obj)
                for _ in range(num):
                    obj = obj.parents[0]
            elif token == "^":
                obj = to_commit(obj)
                if num:
                    obj = obj.parents[num - 1]
            elif token == ":":
