        obj = cast(Commit_ish, name_to_object(repo, rev))
        parsed_to = len(rev)

    if obj is None:
        raise ValueError(f"Revision specifier could not be parsed: {rev}")

    if parsed_to != len(rev):
        raise ValueError(f"Didn't consume complete rev spec {rev}, consumed part: {rev[:parsed_to]}")

    return obj

