    ref = None
    output_type = "commit"
    start = 0

    while start < len(rev):
        if rev[start] not in "^~:@{":
            start += 1
            continue

        token = rev[start]
        start += 1

        if obj is None:
            if start == 0:
                ref = repo.head.ref
            else:
                if token == "@":
                    ref = cast("Reference", name_to_object(repo, rev[:start], return_ref=True))
                else:
                    obj = cast(Commit_ish, name_to_object(repo, rev[:start]))
        else:
            if ref is not None:
                obj = cast("Commit", ref.commit)

        parsed_to = start

        if start < len(rev) and rev[start] == "{":
            end = rev.find("}", start)
            if end == -1:
                raise ValueError(f"Missing closing brace to define type in {rev}")
            output_type = rev[start + 1:end]
            start = end + 1

            if output_type == "commit":
                pass
            elif output_type == "tree":
                try:
                    obj = cast(Commit_ish, obj)
                    obj = to_commit(obj).tree
                except (AttributeError, ValueError):
                    pass
            elif output_type in ("", "blob"):
                obj = cast("TagObject", obj)
                if obj.type == "tag":
                    obj = deref_tag(obj)
            elif token == "@":
                revlog_index = None
                try:
                    revlog_index = -(int(output_type) + 1)
                except ValueError as e:
                    raise NotImplementedError("Support for additional @{...} modes not implemented") from e

                try:
                    entry = ref.log_entry(revlog_index)
                except IndexError as e:
                    raise IndexError(f"Invalid revlog index: {revlog_index}") from e

                obj = Object.new_from_sha(repo, hex_to_bin(entry.newhexsha))
                output_type = ""
            else:
                raise ValueError(f"Invalid output type: {output_type} (in {rev})")

            if output_type and obj and obj.type != output_type:
                raise ValueError(f"Could not accommodate requested object type {output_type}, got {obj.type}")
            parsed_to = start

        num = 0
        if token != ":":
            found_digit = False
            while start < len(rev) and rev[start] in digits:
                num = num * 10 + int(rev[start])
                start += 1
                found_digit = True

            if not found_digit:
                num = 1

        parsed_to = start

        try:
            obj = cast(Commit_ish, obj)
            if token == "~":
                obj = to_commit(obj)
                for _ in range(num):
                    obj = obj.parents[0]
            elif token == "^":
                obj = to_commit(obj)
                if num:
                    obj = obj.parents[num - 1]
            elif token == ":":
                if obj.type != "tree":
                    obj = obj.tree
                obj = obj[rev[start:]]
                parsed_to = len(rev)
            else:
                raise ValueError(f"Invalid token: {token}")
        except (IndexError, AttributeError) as e:
            raise BadName(
                f"Invalid revision spec '{rev}' - not enough "
                f"parent commits to reach '{token}{num}'"
            ) from e

    if obj is None:
        obj = cast(Commit_ish, name_to_object(repo, rev))
        parsed_to = len(rev)

    if obj is None:
        raise ValueError(f"Revision specifier could not be parsed: {rev}")

    if parsed_to != len(rev):
        raise ValueError(f"Didn't consume complete rev spec {rev}, consumed part: {rev[:parsed_to]}")

    return obj

