def to_commit(obj: Object) -> Union["Commit", "TagObject"]:
    """Convert the given object to a commit if possible and return it."""
    if obj.type == "tag":
        obj = deref_tag(obj)

    if obj.type != "commit":
        raise ValueError("Cannot convert object %r to type commit" % obj)
    return obj


def rev_parse(repo: "Repo", rev: str) -> Union["Commit", "Tag", "Tree", "Blob"]:
    """
    :return: Object at the given revision, either Commit, Tag, Tree or Blob
    :param rev: git-rev-parse compatible revision specification as string, please see
        http://www.kernel.org/pub/software/scm/git/docs/git-rev-parse.html
        for details
    :raise BadObject: if the given revision could not be found
    :raise ValueError: If rev couldn't be parsed
    :raise IndexError: If invalid reflog index is specified"""

    if rev.startswith(":/"):
        raise NotImplementedError("commit by message search ( regex )")

    obj: Union[Commit_ish, "Reference", None] = None
    ref = None
    output_type = "commit"
    start = 0
    parsed_to = 0
    lr = len(rev)
    while start < lr:
        if rev[start] not in "^~:@":
            start += 1
            continue

        token = rev[start]
        if obj is None:
            if start == 0:
                ref = repo.head.ref
            else:
                if token == "@":
                    ref = cast("Reference", name_to_object(repo, rev[:start], return_ref=True))
                else:
                    obj = cast(Commit_ish, name_to_object(repo, rev[:start]))
            start += 1
            continue

        if ref is not None:
            obj = cast("Commit", ref.commit)

        start += 1

        if start < lr and rev[start] == "{":
            end = rev.find("}", start)
            if end == -1:
                raise ValueError("Missing closing brace to define type in %s" % rev)
            output_type = rev[start + 1 : end]

            if output_type == "commit":
                pass
            elif output_type == "tree":
                obj = cast(Commit_ish, obj)
                obj = to_commit(obj).tree
            elif output_type in ("", "blob"):
                obj = cast("TagObject", obj)
                if obj.type == "tag":
                    obj = deref_tag(obj)
            elif token == "@":
                revlog_index = None
                try:
                    revlog_index = -(int(output_type) + 1)
                except ValueError as e:
                    raise NotImplementedError("Support for additional @{...} modes not implemented") from e

                try:
                    entry = ref.log_entry(revlog_index)
                except IndexError as e:
                    raise IndexError("Invalid revlog index: %i" % revlog_index) from e

                obj = Object.new_from_sha(repo, hex_to_bin(entry.newhexsha))

                output_type = ""
            else:
                raise ValueError("Invalid output type: %s ( in %s )" % (output_type, rev))

            if output_type and obj and obj.type != output_type:
                raise ValueError("Could not accommodate requested object type %r, got %s" % (output_type, obj.type))
            start = end + 1
            parsed_to = start
            continue

        num = 0
        if token != ":":
            found_digit = False
            while start < lr:
                if rev[start] in digits:
                    num = num * 10 + int(rev[start])
                    start += 1
                    found_digit = True
                else:
                    break
            if not found_digit:
                num = 1

        parsed_to = start
        try:
            obj = cast(Commit_ish, obj)
            if token == "~":
                obj = to_commit(obj)
                for _ in range(num):
                    obj = obj.parents[0]
            elif token == "^":
                obj = to_commit(obj)
                if num:
                    obj = obj.parents[num - 1]
            elif token == ":":
                if obj.type != "tree":
                    obj = obj.tree
                obj = obj[rev[start:]]
                parsed_to = lr
            else:
                raise ValueError("Invalid token: %r" % token)
        except (IndexError, AttributeError) as e:
            raise BadName(
                f"Invalid revision spec '{rev}' - not enough parent commits to reach '{token}{int(num)}'"
            ) from e

    if obj is None:
        obj = cast(Commit_ish, name_to_object(repo, rev))
        parsed_to = lr

    if obj is None:
        raise ValueError("Revision specifier could not be parsed: %s" % rev)

    if parsed_to != lr:
        raise ValueError("Didn't consume complete rev spec %s, consumed part: %s" % (rev, rev[:parsed_to]))

    return obj

