class Repo(object):
    """Represents a git repository and allows you to query references,
    gather commit information, generate diffs, create and clone repositories query
    the log.

    The following attributes are worth using:

    'working_dir' is the working directory of the git command, which is the working tree
    directory if available or the .git directory in case of bare repositories

    'working_tree_dir' is the working tree directory, but will return None
    if we are a bare repository.

    'git_dir' is the .git repository directory, which is always set."""

    DAEMON_EXPORT_FILE = "git-daemon-export-ok"

    git = cast("Git", None)  # Must exist, or  __del__  will fail in case we raise on `__init__()`
    working_dir: PathLike
    _working_tree_dir: Optional[PathLike] = None
    git_dir: PathLike
    _common_dir: PathLike = ""

    # precompiled regex
    re_whitespace = re.compile(r"\s+")
    re_hexsha_only = re.compile("^[0-9A-Fa-f]{40}$")
    re_hexsha_shortened = re.compile("^[0-9A-Fa-f]{4,40}$")
    re_envvars = re.compile(r"(\$(\{\s?)?[a-zA-Z_]\w*(\}\s?)?|%\s?[a-zA-Z_]\w*\s?%)")
    re_author_committer_start = re.compile(r"^(author|committer)")
    re_tab_full_line = re.compile(r"^\t(.*)$")

    unsafe_git_clone_options = [
        # https://git-scm.com/docs/git-clone#Documentation/git-clone.txt---upload-packltupload-packgt
        "--upload-pack",
        "-u",
        # Users can override configuration variables
        # https://git-scm.com/docs/git-clone#Documentation/git-clone.txt---configltkeygtltvaluegt
        "--config",
        "-c",
    ]

    # invariants
    # represents the configuration level of a configuration file
    config_level: ConfigLevels_Tup = ("system", "user", "global", "repository")

    # Subclass configuration
    # Subclasses may easily bring in their own custom types by placing a constructor or type here
    GitCommandWrapperType = Git

    description = property(_get_description, _set_description, doc="the project's description")

    # alias for references
    refs = references

    # alias for heads
    branches = heads

    @property
    def head(self) -> "HEAD":
        """:return: HEAD Object pointing to the current head reference"""
        return HEAD(self, "HEAD")

    def commit(self, rev: Union[str, Commit_ish, None] = None) -> Commit:
        """The Commit object for the specified revision

        :param rev: revision specifier, see git-rev-parse for viable options.
        :return: ``git.Commit``
        """
        if rev is None:
            return self.head.commit
        return self.rev_parse(str(rev) + "^0")

    daemon_export = property(
        _get_daemon_export,
        _set_daemon_export,
        doc="If True, git-daemon may export this repository",
    )

    alternates = property(
        _get_alternates,
        _set_alternates,
        doc="Retrieve a list of alternates paths or set a list paths to be used as alternates",
    )

    rev_parse = rev_parse

    def _get_description(self) -> str:
        desc_path = os.path.join(self.git_dir, "description")
        try:
            with open(desc_path, "r", encoding="utf-8") as f:
                return safe_decode(f.read()).strip()
        except (FileNotFoundError, IOError):
            return ""

    def _set_description(self, value: str) -> None:
        desc_path = os.path.join(self.git_dir, "description")
        with open(desc_path, "w", encoding="utf-8") as f:
            f.write(value.strip())

    def _get_daemon_export(self) -> bool:
        export_file = os.path.join(self.git_dir, self.DAEMON_EXPORT_FILE)
        return os.path.exists(export_file)

    def _set_daemon_export(self, value: bool) -> None:
        export_file = os.path.join(self.git_dir, self.DAEMON_EXPORT_FILE)
        if value:
            touch(export_file)
        else:
            if os.path.exists(export_file):
                os.remove(export_file)

    def _get_alternates(self) -> List[str]:
        alternates_file = os.path.join(self.git_dir, "objects", "info", "alternates")
        if not os.path.exists(alternates_file):
            return []
        with open(alternates_file, "r", encoding="utf-8") as f:
            return [line.strip() for line in f if line.strip()]

    def _set_alternates(self, paths: List[str]) -> None:
        alternates_file = os.path.join(self.git_dir, "objects", "info", "alternates")
        with open(alternates_file, "w", encoding="utf-8") as f:
            for path in paths:
                f.write(f"{path.strip()}\n")
